{"code": "import math

def numeric_integral(func, a, b, n=10000):
    """Simple composite Simpson's rule for numerical integration."""
    h = (b - a) / n
    if n % 2 != 0:
        n += 1 # Ensure even number of intervals for Simpson's rule
        h = (b - a) / n

    def f(x): return func(x)

    total = f(a) + f(b)
    for i in range(1, n):
        x = a + i * h
        if i % 2 == 0:
            total += 2 * f(x)
        else:
            total += 4 * f(x)
    return total * h / 3

def integrand(x, a, b):
    if x <= 0 or x >= 1:
        return 0.0
    val = math.sin(math.log(1/x)) * (x**b - x**a) / math.log(x)
    return val

def calculate_numeric_I(a, b):
    # Handle singularity at x=0 carefully if needed, but the function approaches 0
    # We integrate from epsilon to 1-epsilon
    eps = 1e-9
    # Since the function is well-behaved, we can use the full range with Simpson's on a transformed domain or just skip endpoints.
    # Let's integrate from small to large, excluding 0 and 1 directly by starting/ending slightly off.
    return numeric_integral(lambda t: integrand(t, a, b), eps, 1-eps, n=10000)

# Test cases
test_cases = [(1.0, 2.0), (0.5, 1.5), (0.1, 0.5)]

for a, b in test_cases:
    num_val = calculate_numeric_I(a, b)
    formula_val = math.atan(b + 1) - math.atan(a + 1)
    print(f"a={a}, b={b}")
    print(f"Numerical: {num_val:.10f}")
    print(f"Formula:   {formula_val:.10f}")
    print(f"Difference: {abs(num_val - formula_val):.2e}\n")", "timeout": 30}
